/**
 * Story 370 (explore-11): the AI estimate's unsent input, kept across Back for this session.
 *
 * The description lives in sessionStorage, like the meal editor's draft (story 292), and is
 * bounded the same way by a 30-minute TTL. The photo stays in memory: a 5–12 MB original does not
 * fit in sessionStorage, and in-app navigation keeps this module alive. A reload drops the photo
 * but keeps the text.
 */

const KEY = 'ai-estimate-draft';
const TTL_MS = 30 * 60 * 1000;

let photo: File | null = null;

export interface AiEstimateDraft {
    description: string;
    photo: File | null;
}

export function saveAiEstimateDraft(draft: AiEstimateDraft): void {
    photo = draft.photo;
    if (!draft.description && !draft.photo) {
        sessionStorage.removeItem(KEY);
        return;
    }
    sessionStorage.setItem(KEY, JSON.stringify({ savedAt: Date.now(), description: draft.description }));
}

export function readAiEstimateDraft(): AiEstimateDraft | null {
    const raw = sessionStorage.getItem(KEY);
    // The stored entry is the draft's existence; the in-memory photo only rides along with it.
    if (!raw) {
        photo = null;
        return null;
    }
    const stored = JSON.parse(raw) as { savedAt: number; description: string };
    if (Date.now() - stored.savedAt > TTL_MS) {
        clearAiEstimateDraft();
        return null;
    }
    return { description: stored.description, photo };
}

export function clearAiEstimateDraft(): void {
    photo = null;
    sessionStorage.removeItem(KEY);
}
